using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;

// ---------------------------------------------------------------------------
// Research Agent – uses an AI agent with web-search and note-taking tools
// to investigate a topic, then produce a final summary.
// ---------------------------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.Error.WriteLine("No topic provided – exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// -- Tools ------------------------------------------------------------------

var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (string query) => WebSearchTool.SearchAsync(query),
        nameof(WebSearchTool.SearchAsync),
        "Search the web for information. Returns a list of result snippets with titles and URLs."),

    AIFunctionFactory.Create(
        ([Description("Concise heading for the note")] string title,
         [Description("The body / content of the note")] string content)
            => notebook.AddNote(title, content),
        "AddNote",
        "Save an important finding as a note for later reference."),

    AIFunctionFactory.Create(
        () => notebook.GetNotes(),
        "GetNotes",
        "Retrieve all notes taken so far."),
};

// -- Agent ------------------------------------------------------------------

var innerClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient();

var chatClient = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

var instructions = """
    You are a thorough research agent. Given a topic you must:
    1. Search the web multiple times with varied queries to gather diverse information.
    2. Save every important finding using the AddNote tool (include source URLs).
    3. After collecting enough information, retrieve your notes and write a
       well-structured summary in Markdown with sections, bullet points, and
       source citations.
    Respond ONLY with the final summary – do not include the intermediate steps.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "Researches a topic using web search and note-taking tools.",
    tools: tools);

var response = await agent.RunAsync($"Research the following topic thoroughly: {topic}");

Console.WriteLine("── Research Summary ─────────────────────────────────\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n─────────────────────────────────────────────────────");
Console.WriteLine($"\n📝 Notes collected: {notebook.NoteCount}");

// ===========================================================================
// Web Search Tool – uses Bing search via scraping (no API key required)
// ===========================================================================

static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" }
        }
    };

    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
            var html = await s_http.GetStringAsync(url);

            var results = ParseDuckDuckGoLite(html);

            if (results.Count == 0)
                return $"No results found for '{query}'.";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: {query}\n");
            foreach (var r in results.Take(6))
            {
                sb.AppendLine($"• {r.Title}");
                if (!string.IsNullOrEmpty(r.Url))
                    sb.AppendLine($"  URL: {r.Url}");
                if (!string.IsNullOrEmpty(r.Snippet))
                    sb.AppendLine($"  {r.Snippet}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseDuckDuckGoLite(string html)
    {
        var results = new List<SearchResult>();
        // DuckDuckGo Lite returns results in <a class="result-link"> tags
        // and snippets in <td class="result-snippet"> tags.
        var linkTag = "class=\"result-link\"";
        var snippetTag = "class=\"result-snippet\"";

        var titles = new List<(string Title, string Url)>();
        var snippets = new List<string>();

        var pos = 0;
        while ((pos = html.IndexOf(linkTag, pos, StringComparison.Ordinal)) >= 0)
        {
            // Find the href before the tag
            var aStart = html.LastIndexOf("<a ", pos, Math.Min(pos, 200), StringComparison.Ordinal);
            var href = "";
            if (aStart >= 0)
            {
                var hrefIdx = html.IndexOf("href=\"", aStart, StringComparison.Ordinal);
                if (hrefIdx >= 0 && hrefIdx < pos)
                {
                    hrefIdx += 6;
                    var hrefEnd = html.IndexOf('"', hrefIdx);
                    if (hrefEnd > hrefIdx)
                        href = html[hrefIdx..hrefEnd];
                }
            }

            // Extract text between > and </a>
            var textStart = html.IndexOf('>', pos) + 1;
            var textEnd = html.IndexOf("</a>", textStart, StringComparison.Ordinal);
            var title = textEnd > textStart
                ? StripHtml(html[textStart..textEnd]).Trim()
                : "";

            if (!string.IsNullOrWhiteSpace(title))
                titles.Add((title, href));

            pos = textEnd > 0 ? textEnd : pos + 1;
        }

        pos = 0;
        while ((pos = html.IndexOf(snippetTag, pos, StringComparison.Ordinal)) >= 0)
        {
            var textStart = html.IndexOf('>', pos) + 1;
            var textEnd = html.IndexOf("</td>", textStart, StringComparison.Ordinal);
            var snippet = textEnd > textStart
                ? StripHtml(html[textStart..textEnd]).Trim()
                : "";
            snippets.Add(snippet);
            pos = textEnd > 0 ? textEnd : pos + 1;
        }

        for (int i = 0; i < titles.Count; i++)
        {
            results.Add(new SearchResult
            {
                Title = titles[i].Title,
                Url = titles[i].Url,
                Snippet = i < snippets.Count ? snippets[i] : ""
            });
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        var sb = new StringBuilder(html.Length);
        bool inTag = false;
        foreach (var c in html)
        {
            if (c == '<') { inTag = true; continue; }
            if (c == '>') { inTag = false; continue; }
            if (!inTag) sb.Append(c);
        }
        return System.Net.WebUtility.HtmlDecode(sb.ToString());
    }

    private class SearchResult
    {
        public string Title { get; set; } = "";
        public string Url { get; set; } = "";
        public string Snippet { get; set; } = "";
    }
}

// ===========================================================================
// Notebook – simple in-memory note-taking tool
// ===========================================================================

class Notebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public int NoteCount => _notes.Count;

    public string AddNote(string title, string content)
    {
        _notes.Add((title, content, DateTime.UtcNow));
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
        {
            var (title, content, ts) = _notes[i];
            sb.AppendLine($"--- Note #{i + 1}: {title} ({ts:u}) ---");
            sb.AppendLine(content);
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

